import json, os, re, subprocess, datetime
from playwright.sync_api import sync_playwright

BASE = os.environ.get('HI8_BASE', 'http://localhost:8801')
PSQL = ['psql', '-h', os.environ.get('PGHOST', '127.0.0.1'), '-p', os.environ.get('PGPORT', '5440'), '-U', 'postgres',
        '-d', os.environ.get('PGDATABASE', 'hi8'), '-qAt', '-v', 'ON_ERROR_STOP=1']
ok = 0
def sql(q):
    r = subprocess.run(PSQL + ['-c', q], capture_output=True, text=True)
    if r.returncode: raise SystemExit('SQL failed: ' + r.stderr)
    return r.stdout.strip()
def check(cond, what):
    global ok
    if not cond: raise SystemExit('FAIL: ' + what)
    ok += 1; print('  ok ·', what)
import urllib.request
def rpc(fn, body, ip='10.4.4.4'):
    req = urllib.request.Request(f'{BASE}/rest/v1/rpc/{fn}', data=json.dumps(body).encode(), method='POST', headers={'apikey': 'sb_publishable_test', 'content-type': 'application/json', 'x-test-ip': ip})
    try:
        with urllib.request.urlopen(req) as r: return json.loads(r.read() or b'null')
    except urllib.error.HTTPError as e: return json.loads(e.read() or b'null')
def txt(pg, sel='body'):  # headings are upper-cased by CSS; what's folded under MORE has no rendered text, so read its words
    t = pg.inner_text(sel)
    if not t.strip(): t = pg.evaluate('s => { const e = document.querySelector(s); if (!e) return ""; const w = document.createTreeWalker(e, NodeFilter.SHOW_TEXT); let o = [], n; while ((n = w.nextNode())) o.push(n.nodeValue); return o.join(" "); }', sel)
    return re.sub(r'\s+', ' ', t).upper()

